CREATE TABLE customers (
  customer_id   NUMBER        PRIMARY KEY,
  customer_name VARCHAR2(60)  NOT NULL,
  city          VARCHAR2(30),
  phone         VARCHAR2(20),
  credit_limit  NUMBER(8,2)
);

INSERT INTO customers VALUES (1, 'Asha Rao', 'Pune', '9876543210', 50000);
INSERT INTO customers VALUES (2, 'Venkata Subrahmanya Lakshmi Narasimha', 'Hyderabad', '98765 43211', 125000);
INSERT INTO customers VALUES (3, 'Ravi Kumar', NULL, NULL, NULL);
COMMIT;

DECLARE
  v_name VARCHAR2(20);
BEGIN
  SELECT customer_name
    INTO v_name
    FROM customers
   WHERE customer_id = 2;
  DBMS_OUTPUT.PUT_LINE(v_name);
END;
/

DECLARE
  v_name customers.customer_name%TYPE;
BEGIN
  SELECT customer_name
    INTO v_name
    FROM customers
   WHERE customer_id = 2;
  DBMS_OUTPUT.PUT_LINE(v_name);
END;
/

DECLARE
  v_list VARCHAR2(30);
BEGIN
  FOR r IN (SELECT customer_name FROM customers ORDER BY customer_id) LOOP
    v_list := v_list || r.customer_name || ',';
  END LOOP;
  DBMS_OUTPUT.PUT_LINE(v_list);
END;
/

DECLARE
  v_list CLOB;
BEGIN
  FOR r IN (SELECT customer_name FROM customers ORDER BY customer_id) LOOP
    v_list := v_list || r.customer_name || ',';
  END LOOP;
  DBMS_OUTPUT.PUT_LINE(RTRIM(v_list, ','));
END;
/

DECLARE
  v_city VARCHAR2(10 CHAR);  -- 10 characters
BEGIN
  v_city := 'पुणे';
  DBMS_OUTPUT.PUT_LINE(v_city || ' bytes=' || LENGTHB(v_city));
END;
/

DECLARE
  v_amt NUMBER(5,2);
BEGIN
  v_amt := 123.456;
  DBMS_OUTPUT.PUT_LINE(v_amt);
END;
/

DECLARE
  v_phone_num NUMBER;
  v_phone     customers.phone%TYPE;
BEGIN
  SELECT phone INTO v_phone FROM customers WHERE customer_id = 2;
  v_phone_num := v_phone;     -- implicit conversion in PL/SQL
END;
/

DECLARE
  v_limit NUMBER NOT NULL := 0;
BEGIN
  SELECT credit_limit
    INTO v_limit
    FROM customers
   WHERE customer_id = 3;
END;
/

BEGIN
  DECLARE
    v_name VARCHAR2(20);
  BEGIN
    SELECT customer_name INTO v_name
      FROM customers WHERE customer_id = 2;
  END;
EXCEPTION
  WHEN VALUE_ERROR THEN
    DBMS_OUTPUT.PUT_LINE(SQLERRM);
    DBMS_OUTPUT.PUT_LINE(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
    RAISE;
END;
/

